INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''care label'' on a garment primarily meant to communicate?', '["Instructions for how to properly wash, dry, iron, and otherwise care for the garment without damaging it","The garment''s retail price and store location","The exact fiber content percentage only, with no care instructions","The name of the garment''s designer"]'::jsonb, 'Instructions for how to properly wash, dry, iron, and otherwise care for the garment without damaging it', 'Care labels use standardized symbols/text to instruct consumers on appropriate washing temperature, drying method, ironing, and other care actions — helping prevent damage from improper care (shrinkage, color loss, fabric degradation).', 1, '{"care-label"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'Why must a care label''s instructions be based on ACTUAL testing of the specific fabric/garment, rather than generic assumptions?', '["Different fabric/finish/dye combinations can behave very differently under the same care conditions, so generic assumptions could recommend care that damages that specific garment","Care label instructions are purely decorative and have no real testing basis in any garment","All fabrics behave identically regardless of fiber content, finish, or dye class","Generic care instructions are always safe for every possible fabric type with zero risk"]'::jsonb, 'Different fabric/finish/dye combinations can behave very differently under the same care conditions, so generic assumptions could recommend care that damages that specific garment', 'Since fiber content, finish treatments, and dye class all affect how a specific fabric responds to washing/drying/ironing, care labels should be based on actual testing of that garment''s specific fabric — a generic assumption could recommend conditions that cause shrinkage, color bleeding, or other damage.', 2, '{"care-label-testing"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''colorfastness to washing'' testing meant to evaluate for a finished garment?', '["How well the garment''s dyed color resists fading or bleeding when subjected to standardized washing conditions","The garment''s physical strength when stretched","The exact shade name/code used in production","The garment''s resistance to wrinkling"]'::jsonb, 'How well the garment''s dyed color resists fading or bleeding when subjected to standardized washing conditions', 'Wash fastness testing exposes a sample to standardized washing conditions (detergent, temperature, agitation), then evaluates both color change on the sample itself and any color staining transferred to an adjacent test fabric.', 1, '{"wash-fastness-testing"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is ''pilling resistance'' testing meant to evaluate for a knitted or woven fabric?', '["How resistant the fabric is to forming small tangled fiber balls (pills) on its surface from rubbing/abrasion during normal wear","The fabric''s resistance to color fading from sunlight","The fabric''s exact GSM measurement","The fabric''s resistance to shrinking after washing"]'::jsonb, 'How resistant the fabric is to forming small tangled fiber balls (pills) on its surface from rubbing/abrasion during normal wear', 'Pilling tests (like the Martindale abrasion method) simulate the repeated rubbing a fabric experiences during normal wear, then rate how much pilling (small fiber balls) forms on the surface — an important comfort and appearance quality metric, especially for knitwear.', 1, '{"pilling-test"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What is a ''seam slippage'' test meant to evaluate for a woven fabric?', '["How resistant a sewn seam is to yarns pulling apart/slipping at the stitch line under tension","The exact thread color used in a seam","The total number of stitches per inch in a seam","The fabric''s resistance to color bleeding when wet"]'::jsonb, 'How resistant a sewn seam is to yarns pulling apart/slipping at the stitch line under tension', 'Seam slippage testing applies controlled tension to a sewn seam and measures how much the fabric yarns shift/pull apart at the stitch line — important for loosely woven or low-density fabrics, which are more prone to this seam failure mode.', 2, '{"seam-slippage-test"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'Why are loosely woven, low-density fabrics generally MORE prone to seam slippage than tightly woven, high-density fabrics of similar yarn count?', '["Lower thread density means less inter-yarn friction holding the fabric structure together, making it easier for yarns near a seam to shift/pull apart under tension","Thread density has no relationship to a fabric''s seam slippage tendency","Loosely woven fabrics are always stronger overall than tightly woven fabrics","Seam slippage only depends on thread color, not fabric density"]'::jsonb, 'Lower thread density means less inter-yarn friction holding the fabric structure together, making it easier for yarns near a seam to shift/pull apart under tension', 'Since fabric structural integrity relies partly on friction between closely packed interlacing yarns, a lower-density (more loosely woven) fabric has less of this friction holding yarns in place — making it easier for yarns near a seam to shift and slip apart when the seam is put under tension.', 2, '{"seam-slippage-cause"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What is ''bursting strength'' testing typically used to evaluate, and for what type of fabric is it especially relevant?', '["The force needed to rupture a fabric by pushing a probe through it in a multi-directional stress pattern; especially relevant for knitted fabrics, which don''t have clear warp/weft directions for standard tensile testing","A test used only to measure fabric color depth, unrelated to strength","A test that measures only a single-direction pulling force, identical to standard tensile testing","A test used exclusively on non-woven materials, never on knitted fabric"]'::jsonb, 'The force needed to rupture a fabric by pushing a probe through it in a multi-directional stress pattern; especially relevant for knitted fabrics, which don''t have clear warp/weft directions for standard tensile testing', 'Bursting strength tests apply multi-directional stress (pushing a probe/diaphragm through the fabric until it ruptures) rather than single-direction pulling — well suited to knitted fabrics, which lack the clear directional warp/weft structure that standard tensile (grab/strip) tests are designed around.', 2, '{"bursting-strength-test"}'::text[]);
